const cloud = (x, y, k = 1) => `<g transform="translate(${x} ${y}) scale(${k})" fill="#fff"><ellipse cx="0" cy="4" rx="28" ry="15"/><ellipse cx="22" cy="-8" rx="22" ry="18"/><ellipse cx="46" cy="4" rx="24" ry="14"/></g>`;
