const butterfly = (x, y, c, k = 1) => `<g transform="translate(${x} ${y}) scale(${k})"><ellipse cx="-6" cy="-3" rx="7" ry="9" fill="${c}" transform="rotate(-25 -6 -3)"/><ellipse cx="6" cy="-3" rx="7" ry="9" fill="${c}" transform="rotate(25 6 -3)"/><ellipse cx="-5" cy="6" rx="4.5" ry="5" fill="${c}" opacity=".8"/><ellipse cx="5" cy="6" rx="4.5" ry="5" fill="${c}" opacity=".8"/><rect x="-1.4" y="-8" width="2.8" height="16" rx="1.4" fill="#2D3436"/></g>`;
