    s += '<g transform="translate(214 62) rotate(18)"><path d="M0 -32l24 32-24 36-24-36z" fill="#FF6B6B"/><path d="M0 -32l24 32H0z" fill="#FECA57"/><path d="M0 4l-24-4 24 36z" fill="#54A0FF"/><path d="M0 -32v68M-24 0h48" stroke="#fff" stroke-width="2.5"/></g>'
      + '<path d="M222 100c12 26-6 46 6 72" stroke="#3D4A66" stroke-width="2" fill="none"/>'
      + '<path d="M218 120l-6-5v10zM218 120l6-5v10zM222 146l-6-5v10zM222 146l6-5v10zM226 168l-6-5v10zM226 168l6-5v10z" fill="#A55EEA"/>';
